#include "pg/pg.h"
#include "core/gil.h"
#include "data/datastore.h"
#include "sim/pvp/battle_api.h"
#include "sim/typed72_app/cold_export.h"
#include "sim/typed72_app/session.h"
#include <nlohmann/json.hpp>
#include <fstream>
#include <iostream>
using namespace pvz;using J=nlohmann::json;
namespace {
void require(bool value,const std::string& message){if(!value)throw std::runtime_error(message);}
struct Fixture {
 BattleHandle handle;std::unique_ptr<typed72app::Session> battle;
 Fixture():handle(battle_from_scenario({{"seed",742},{"fixture_flat",true},{"night",true},
   {"decks",{{"plant",{"plant:磁力菇","plant:吸金磁","plant:坚果"}},
              {"zombie",{"zombie:脑光墓碑","zombie:巨人僵尸","zombie:角斗士巨人","zombie:红眼巨人","zombie:吸金磁僵尸"}}}}})){
   battle=typed72app::Session::create(typed72app::export_cold(handle.battle,742),"carried-imp independent equipment audit");
   for(const char* side:{"plant","zombie"})battle->fixture_set_avatar(side,{{"玩家位置",{3200,96,0,0}},{"_pvp_butter",1.e8}});
 }
 ~Fixture(){try{callm(handle.battle,SY("close"),Args{});}catch(...) {}}
 std::string spawn(const std::string& name,double x=1680.,double y=960.){
   const auto id=battle->spawn("zombie:"+name,"zombie",x,y,-1.,false);require(bool(id),"spawn rejected "+name);
   require(battle->fixture_place_zombie(*id,x,y,-1.),"placement failed");battle->native_set(false,*id,{{"出场",500.}});return *id;
 }
 J zombie(const std::string& id){const auto view=battle->native_view();for(const auto& z:view.at("g").at("僵尸"))if(z.value("_pvp_id",std::string{})==id)return z;throw std::runtime_error("zombie missing "+id);}
 J plant(const std::string& id){const auto view=battle->native_view();for(const auto& p:view.at("g").at("植物"))if(p.value("_pvp_id",std::string{})==id)return p;throw std::runtime_error("plant missing "+id);}
 J events(){J out=J::array();for(size_t i=0;i<battle->log_size();++i)out.push_back(battle->log_entry(i));return out;}
 template<class Predicate>void until(Predicate check,int limit,const std::string& reason){for(int i=0;i<limit;++i){battle->step();if(check())return;}throw std::runtime_error(reason+": "+battle->native_view().dump());}
 std::string thrown(const std::string& carrier){
   const auto before=zombie(carrier);battle->native_set(false,carrier,{{"血量",before.at("半血").get<double>()}});
   std::string result;until([&]{const auto view=battle->native_view();for(const auto& z:view.at("g").at("僵尸"))if(z.value("_pvp_card",std::string{})=="zombie:小鬼僵尸")result=z.at("_pvp_id");return !result.empty();},8,"giant did not throw a registered imp");return result;
 }
 void activate(const std::string& magnet){battle->native_set(false,magnet,{{"__pvz_sb_gold_magnet_zombie_cd",0.}});for(int i=0;i<2;++i)battle->step();}
};
J armor(const J& z){J out;for(const char* k:{"_pvp_id","_pvp_card","防具","防具血量","_pvp_armor_max","_pvp_imp_armor","_pvp_imp_armor_hp","_pvp_black_armor","丢小鬼","魅惑","_pvp_thrown_by","_pvp_grabbed_by"})if(z.contains(k))out[k]=z[k];return out;}
void expect_back(const J& z,const std::string& kind,double hp){require(z.value("_pvp_imp_armor",std::string{})==kind&&z.value("_pvp_imp_armor_hp",0.)==hp,"carried equipment differs: "+armor(z).dump());}
}
int main(int argc,char** argv){
 if(argc<2||!std::getenv("PVP_USERDATA"))return 2;SDL_SetMainReady();gil::init();data::set_data_dir("extract/data");pg::install_pygame();init_pvp_modules();
 J checks=J::array();int failures=0;auto test=[&](const char* name,auto fn){J row={{"name",name}};try{row["evidence"]=fn();row["passed"]=true;}catch(const std::exception& e){row["passed"]=false;row["error"]=e.what();++failures;}J brief=row;brief.erase("evidence");std::cerr<<brief.dump()<<std::endl;checks.push_back(std::move(row));};
 test("natural_gladiator_thrown_imp_inherits_375hp_black_bucket",[]{Fixture f;const auto giant=f.spawn("角斗士巨人");const auto before=f.zombie(giant);expect_back(before,"黑铁桶",375.);const auto imp=f.thrown(giant);const auto child=f.zombie(imp),after=f.zombie(giant);
   require(child.at("防具")=="铁桶"&&child.at("防具血量")==375.&&child.at("_pvp_armor_max")==375.,"natural black bucket not inherited: "+armor(child).dump());require(child.at("_pvp_black_armor")=="黑铁桶僵尸","black armor identity absent");expect_back(after,"",0.);require(after.at("防具")==before.at("防具")&&after.at("防具血量")==before.at("防具血量"),"carrier own helmet changed during throw");
   bool parent=false;for(const auto& e:f.events())if(e.value("event",std::string{})=="spawn"&&e.value("entity",std::string{})==imp)parent=e.value("parent_entity",std::string{})==giant;require(parent,"thrown imp lost its carrier parent identity");return J{{"before",armor(before)},{"carrier_after",armor(after)},{"child",armor(child)}};});
 test("ordinary_giant_preserves_partial_durability_and_exact_armor_identity",[]{J rows=J::array();for(const auto& item:std::vector<std::pair<std::string,double>>{{"铁桶",173.25},{"黑铁桶",112.25},{"黑路障",63.5},{"黑橄榄球头盔",87.75}}){Fixture f;const auto giant=f.spawn("巨人僵尸");f.battle->native_set(false,giant,{{"防具","铁桶"},{"防具血量",211.},{"_pvp_armor_max",250.},{"_pvp_imp_armor",item.first},{"_pvp_imp_armor_hp",item.second}});const auto imp=f.thrown(giant);const auto child=f.zombie(imp),carrier=f.zombie(giant);const auto expected=item.first=="黑铁桶"?"铁桶":item.first=="黑路障"?"路障":item.first;
   require(child.at("防具")==expected&&child.at("防具血量")==item.second&&child.at("_pvp_armor_max")==item.second,"partial armor transfer differs: "+armor(child).dump());require(carrier.at("防具")=="铁桶"&&carrier.at("防具血量")==211.,"independent carrier slot changed");expect_back(carrier,"",0.);if(item.first=="黑铁桶"||item.first=="黑路障")require(child.at("_pvp_black_armor")==item.first+"僵尸","black identity changed");rows.push_back({{"carried_kind",item.first},{"carried_hp",item.second},{"child",armor(child)},{"carrier",armor(carrier)}});}return rows;});
 test("gold_magnet_gifts_two_independent_slots_without_overwriting",[]{Fixture f;const auto giant=f.spawn("巨人僵尸"),magnet=f.spawn("吸金磁僵尸",1536.);f.activate(magnet);const auto first=f.zombie(giant);require(first.at("防具")=="铁桶"&&first.at("防具血量")==250.&&first.at("_pvp_armor_max")==250.,"first gift did not equip giant head/max durability: "+armor(first).dump());expect_back(first,"",0.);f.activate(magnet);const auto second=f.zombie(giant);expect_back(second,"铁桶",250.);require(second.at("防具")==first.at("防具")&&second.at("防具血量")==first.at("防具血量")&&second.at("_pvp_armor_max")==250.,"second gift overwrote giant head/max durability");f.activate(magnet);const auto third=f.zombie(giant);expect_back(third,"铁桶",250.);require(third.at("防具血量")==250.,"third gift changed occupied equipment");const auto imp=f.thrown(giant);const auto child=f.zombie(imp);require(child.at("防具")=="铁桶"&&child.at("防具血量")==250.,"naturally gifted riding bucket lost on throw");f.activate(magnet);expect_back(f.zombie(giant),"",0.);return J{{"first",armor(first)},{"second",armor(second)},{"third",armor(third)},{"thrown",armor(child)}};});
 test("gold_magnet_preserves_all_existing_head_armor_kinds",[]{J rows=J::array();for(const char* armor_kind:{"黑路障","黑铁桶","南瓜头防具"})for(const char* kind:{"普通僵尸","巨人僵尸"}){Fixture f;const auto wearer=f.spawn(kind),magnet=f.spawn("吸金磁僵尸",1536.);f.battle->native_set(false,wearer,{{"防具",armor_kind},{"防具血量",73.5},{"_pvp_armor_max",200.}});f.activate(magnet);const auto after=f.zombie(wearer);require(after.at("防具")==armor_kind&&after.at("防具血量")==73.5&&after.at("_pvp_armor_max")==200.,"gift overwrote occupied armor: "+armor(after).dump());if(std::string(kind)=="巨人僵尸")expect_back(after,"铁桶",250.);else expect_back(after,"",0.);rows.push_back({{"kind",kind},{"armor",armor_kind},{"after",::armor(after)}});}return rows;});
 test("absent_dead_and_charmed_carriers_never_receive_a_phantom_back_slot",[]{J rows=J::array();for(const char* state:{"already_thrown","redeye","dead","charmed"}){Fixture f;const auto giant=f.spawn(std::string(state)=="redeye"?"红眼巨人":"巨人僵尸"),magnet=f.spawn("吸金磁僵尸",1536.);f.battle->native_set(false,giant,{{"防具","铁桶"},{"防具血量",250.}});if(std::string(state)=="already_thrown")f.battle->native_set(false,giant,{{"丢小鬼",0.}});if(std::string(state)=="dead")f.battle->native_set(false,giant,{{"血量",0.}});if(std::string(state)=="charmed")f.battle->native_set(false,giant,{{"魅惑",200.}});f.activate(magnet);const auto view=f.battle->native_view();for(const auto& z:view.at("g").at("僵尸"))if(z.value("_pvp_id",std::string{})==giant)expect_back(z,"",0.);const auto source=f.zombie(magnet);require(source.value("__pvz_sb_gold_magnet_zombie_cd",500.)<20.,"magnet gifted an absent/dead/friendly-carried ghost: "+source.dump());rows.push_back({{"state",state},{"magnet_cd",source["__pvz_sb_gold_magnet_zombie_cd"]}});}return rows;});
 test("charmed_gold_magnet_absorbs_body_then_carried_metal_without_blast",[]{Fixture f;const auto giant=f.spawn("角斗士巨人"),magnet=f.spawn("吸金磁僵尸",1536.);f.battle->native_set(false,magnet,{{"魅惑",200.}});f.activate(magnet);const auto first=f.zombie(giant);require(first.at("防具")==""&&first.at("防具血量")==0.,"charmed magnet did not strip own giant helmet");expect_back(first,"黑铁桶",375.);f.activate(magnet);const auto second=f.zombie(giant);expect_back(second,"",0.);for(const auto& e:f.events())require(e.value("event",std::string{})!="black_armor","whole-armor absorption fired break blast");return J{{"first",armor(first)},{"second",armor(second)}};});
 test("plant_magnets_absorb_both_slots_one_at_a_time",[]{J rows=J::array();for(const char* kind:{"磁力菇","吸金磁"}){Fixture f;const auto giant=f.spawn("角斗士巨人");const auto id=f.battle->spawn(std::string("plant:")+kind,"plant",1536.,960.,1.,false);require(bool(id),"plant magnet spawn rejected");f.until([&]{return f.zombie(giant).at("防具")=="";},5,std::string(kind)+" failed to take giant helmet");const auto first=f.zombie(giant);expect_back(first,"黑铁桶",375.);f.battle->native_set(false,*id,{{"吸",0.}});f.until([&]{return f.zombie(giant).value("_pvp_imp_armor_hp",0.)==0.;},5,std::string(kind)+" failed to take carried metal");const auto second=f.zombie(giant);for(const auto& e:f.events())require(e.value("event",std::string{})!="black_armor","plant absorption fired black armor blast");rows.push_back({{"plant",kind},{"first",armor(first)},{"second",armor(second)},{"magnet",f.plant(*id)}});}return rows;});
 test("redeye_throws_existing_armored_imp_without_changing_its_equipment",[]{Fixture f;const auto giant=f.spawn("红眼巨人"),imp=f.spawn("小鬼僵尸",1704.);f.battle->native_set(false,imp,{{"防具","铁桶"},{"防具血量",173.25},{"_pvp_armor_max",375.},{"_pvp_black_armor","黑铁桶僵尸"},{"黄油",1.e8}});f.battle->native_set(false,giant,{{"_pvp_throw_clock",1999.}});f.until([&]{return f.zombie(imp).value("_pvp_grabbed_by",std::string{})==giant;},5,"redeye did not grab existing imp");const auto held=f.zombie(imp);f.until([&]{return f.zombie(imp).value("_pvp_thrown_by",std::string{})==giant;},60,"redeye did not throw held imp");const auto thrown=f.zombie(imp);require(held.at("防具")==thrown.at("防具")&&thrown.at("防具血量")==173.25&&thrown.at("_pvp_armor_max")==375.&&thrown.at("_pvp_black_armor")=="黑铁桶僵尸","redeye recreated or stripped existing imp armor");return J{{"held",armor(held)},{"thrown",armor(thrown)}};});
 J report={{"passed",failures==0},{"failures",failures},{"checks",checks},{"scope","Actual production Session native giant summons, gold-magnet service activations, PlantRegion magnets and redeye grab/throw. Isolated seeded flat night fixture. Broken-armor secondhand drops are audited separately; absorption must not break armor or blast."}};std::ofstream(argv[1])<<report.dump(2);return failures?1:0;
}
